insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-155', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'As the reaction quotient $Q$ of a galvanic cell increases, the cell EMF generally', '["decreases","increases without limit","jumps discontinuously to $E^\\circ$","becomes independent of $n$"]'::jsonb, 0, '$E = E^\circ - (RT/nF)\ln Q$, so a larger $Q$ reduces $E$. At equilibrium $Q = K$ and $E = 0$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'nernst') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
