insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-156', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'For the half-cell $\mathrm{M}^{n+} + n\,e^- \rightarrow \mathrm{M}(s)$, the Nernst expression at 298 K is', '["$E = E^\\circ + (0.059/n)\\log[\\mathrm{M}^{n+}]$","$E = E^\\circ - (0.059/n)\\log[\\mathrm{M}^{n+}]$","$E = E^\\circ + 0.059\\,n\\,[\\mathrm{M}^{n+}]$","$E = (0.059/n)/[\\mathrm{M}^{n+}]$"]'::jsonb, 0, 'Solid metal has activity 1, so $Q = 1/[\mathrm{M}^{n+}]$ and the sign of the log term flips.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'nernst') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
