insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-163', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'For $\mathrm{Cu}|\mathrm{Cu^{2+}}(0.010\ \mathrm{M})||\mathrm{Cu^{2+}}(1.0\ \mathrm{M})|\mathrm{Cu}$ at 298 K the EMF is', '["$0.059\\ \\mathrm{V}$","$0.029\\ \\mathrm{V}$","$0.118\\ \\mathrm{V}$","$0.34\\ \\mathrm{V}$"]'::jsonb, 0, '$E^\circ = 0$ and $n = 2$, so $E = (0.059/2)\log(1.0/0.010) = 0.0295 \times 2 = 0.059\ \mathrm{V}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'nernst') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
